<?php
if(!isset($db)){http_response_code(404);exit;}
function bookingSetup(){global $db;
$db->exec("CREATE TABLE IF NOT EXISTS onb_bookings(id INT AUTO_INCREMENT PRIMARY KEY,ref VARCHAR(24) UNIQUE NOT NULL,trip_id INT NOT NULL,user_id INT NOT NULL,agent_id INT NULL,stage VARCHAR(24) NOT NULL DEFAULT 'quote',price DECIMAL(12,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(trip_id,stage),FOREIGN KEY(trip_id) REFERENCES trips(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB");
$db->exec("CREATE TABLE IF NOT EXISTS onb_booking_money(id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL,kind VARCHAR(12) NOT NULL,amount DECIMAL(12,2) NOT NULL,reference VARCHAR(150) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES onb_bookings(id)) ENGINE=InnoDB");
$db->exec("CREATE TABLE IF NOT EXISTS onb_booking_expenses(id INT AUTO_INCREMENT PRIMARY KEY,trip_id INT NOT NULL,category VARCHAR(100) NOT NULL,amount DECIMAL(12,2) NOT NULL,reference VARCHAR(150) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(trip_id) REFERENCES trips(id)) ENGINE=InnoDB");
}
function bookingCancellationSetup(){q("CREATE TABLE IF NOT EXISTS onb_cancellation_requests(booking_id INT PRIMARY KEY,reason VARCHAR(1000) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',response VARCHAR(1000) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,reviewed_at DATETIME NULL) ENGINE=InnoDB");}
function bookingCancellationAction($action,$u,$admin){global $db;if(!$u)throw new RuntimeException('Sign in required.');bookingSetup();bookingCancellationSetup();departureSetup();depCheckoutSetup();$id=(int)p('id');$db->beginTransaction();try{$b=q('SELECT * FROM onb_bookings WHERE id=? FOR UPDATE',[$id])->fetch();if(!$b||(!$admin&&(int)$b['user_id']!==(int)$u['id']))throw new RuntimeException('Booking not found.');if($action==='booking_cancel_request'&&!$admin){$reason=trim(p('reason'));if(!in_array($b['stage'],['accepted','confirmed'],true)||$reason===''||strlen($reason)>1000)throw new RuntimeException('Enter a valid cancellation reason for an active booking.');if(q('SELECT 1 FROM onb_cancellation_requests WHERE booking_id=?',[$id])->fetchColumn())throw new RuntimeException('A request already exists. Contact our team for changes.');q('INSERT INTO onb_cancellation_requests(booking_id,reason) VALUES(?,?)',[$id,$reason]);}elseif($action==='booking_cancel_review'&&$admin){$status=p('status');$response=trim(p('response'));if(!in_array($status,['approved','declined'],true)||$response===''||strlen($response)>1000)throw new RuntimeException('Select a decision and enter a response.');$request=q('SELECT status FROM onb_cancellation_requests WHERE booking_id=? FOR UPDATE',[$id])->fetchColumn();if($request!=='pending')throw new RuntimeException('No pending request.');if($status==='approved'){if(!in_array($b['stage'],['accepted','confirmed'],true))throw new RuntimeException('Booking is no longer active.');q("UPDATE onb_bookings SET stage='cancelled' WHERE id=?",[$id]);q("UPDATE onb_departure_requests r JOIN onb_checkout x ON x.request_id=r.id SET r.status='declined' WHERE x.booking_id=?",[$id]);}q('UPDATE onb_cancellation_requests SET status=?,response=?,reviewed_at=NOW() WHERE booking_id=?',[$status,$response,$id]);}else throw new RuntimeException('Access denied.');$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}go('page=bookings');}
function bookingCancellationView($b,$admin){$r=q('SELECT * FROM onb_cancellation_requests WHERE booking_id=?',[$b['id']])->fetch();echo '<section class="onb-luxe-card"><h3>Cancellation request</h3>';if($r){echo '<p>Status: '.h(ucfirst($r['status'])).' · Submitted '.h($r['created_at']).'</p><p>Reason: '.h($r['reason']).'</p>';if($r['response'])echo '<p>Team response: '.h($r['response']).'</p>';if($admin&&$r['status']==='pending'){form('booking_cancel_review');echo '<input type="hidden" name="id" value="'.h($b['id']).'"><label>Decision<select name="status"><option value="approved">Approve and cancel booking</option><option value="declined">Decline request</option></select></label><label>Response<textarea name="response" required maxlength="1000"></textarea></label><button>Save decision</button></form><p>Review applicable refund policy and record any refund separately. Approval does not send money.</p>';}}elseif(!$admin&&in_array($b['stage'],['accepted','confirmed'],true)){echo '<p>Submitting a request does not immediately cancel your booking or guarantee a refund. Standard bookings are non-refundable for voluntary cancellation, subject to applicable law and visa refusal or organizer cancellation policies. Flexible bookings may qualify for a refund less non-recoverable expenses and the service fee.</p>';form('booking_cancel_request');echo '<input type="hidden" name="id" value="'.h($b['id']).'"><label>Reason for cancellation<textarea name="reason" required maxlength="1000"></textarea></label><button>Submit cancellation request</button></form>';}else echo '<p>No cancellation request.</p>';echo '</section>';}
function bookingPolicySetup(){q("CREATE TABLE IF NOT EXISTS onb_booking_policy(booking_id INT PRIMARY KEY,departure DATE NOT NULL,visa VARCHAR(20) NOT NULL DEFAULT 'pending',flexible TINYINT NOT NULL DEFAULT 0,insurance TINYINT NOT NULL DEFAULT 0,cancel_reason VARCHAR(30) NULL,nonrecoverable DECIMAL(12,2) NOT NULL DEFAULT 0) ENGINE=InnoDB");}
function bookingPolicyView($b,$admin){bookingPolicySetup();$v=q('SELECT * FROM onb_booking_policy WHERE booking_id=?',[$b['id']])->fetch();if($v){$price=(float)$b['price'];$deposit=min(500,$price);$target=max($deposit,round($price*.6,2));$net=bookingNet($b['id']);echo '<article class="onb-luxe-card"><h3>Payment milestones</h3><p>Deposit CAD '.number_format($deposit,2).' · Visa approval instalment CAD '.number_format($target-$deposit,2).' · Final instalment CAD '.number_format($price-$target,2).'</p><p>Final due '.h(date('Y-m-d',strtotime($v['departure'].' -15 days'))).' · Visa: '.h($v['visa']).' · Outstanding CAD '.number_format(max(0,$price-$net),2).'</p><p>'.($v['flexible']?'Flexible booking (included in quoted total)':'Standard booking').' · Insurance '.($v['insurance']?'requested':'not requested').'</p>';if($v['cancel_reason']){$deduct=$v['cancel_reason']==='organizer'?0:($v['cancel_reason']==='visa'?200:($v['flexible']?200+(float)$v['nonrecoverable']:$price));echo '<p>Estimated additional refund CAD '.number_format(max(0,$net-$deduct),2).' (review before issuing; no automatic transfer).</p>';}echo '</article>';}if($admin){form('booking_policy');echo '<input type="hidden" name="id" value="'.h($b['id']).'">';field('departure','Departure date',$v['departure']??'','date');echo '<label>Visa status<select name="visa">';foreach(['pending','approved','refused','not_required'] as $x)echo '<option '.(($v['visa']??'pending')===$x?'selected':'').'>'.h($x).'</option>';echo '</select></label><label><input type="checkbox" name="flexible" value="1" '.(!empty($v['flexible'])?'checked':'').'> Flexible booking: CAD 200 already included in quoted total</label><label><input type="checkbox" name="insurance" value="1" '.(!empty($v['insurance'])?'checked':'').'> Insurance requested</label><label>Cancellation reason<select name="cancel_reason"><option value="">None</option>';foreach(['voluntary','visa','organizer'] as $x)echo '<option '.(($v['cancel_reason']??'')===$x?'selected':'').'>'.h($x).'</option>';echo '</select></label>';field('nonrecoverable','Documented non-recoverable expenses CAD',$v['nonrecoverable']??'0');echo '<button>Save booking policy details</button></form>';}}
function bookingAmount($key){$v=p($key);if(!preg_match('/^\d{1,9}(\.\d{1,2})?$/D',$v)||(float)$v<=0)throw new RuntimeException('Enter a positive CAD amount with at most two decimals.');return $v;}
function bookingNet($id){return (float)q("SELECT COALESCE(SUM(CASE WHEN kind='payment' THEN amount ELSE -amount END),0) FROM onb_booking_money WHERE booking_id=?",[$id])->fetchColumn();}
function bookingAction($action,$admin){global $db;if(!$admin)throw new RuntimeException('Access denied.');bookingSetup();bookingPolicySetup();growthSetup();agentSetup();departureSetup();depCheckoutSetup();businessMailSetup();$db->beginTransaction();try{
if($action==='booking_create'){$trip=(int)p('trip_id');$uid=q("SELECT id FROM users WHERE email=? AND role='traveller'",[strtolower(p('email'))])->fetchColumn();if(!$uid||!q('SELECT id FROM trips WHERE id=?',[$trip])->fetchColumn())throw new RuntimeException('Select a valid trip and registered traveller.');$agent=(int)p('agent_id');if($agent&&!agentActive($agent))throw new RuntimeException('Invalid agent.');$price=(float)bookingAmount('price');$code=strtoupper(p('discount'));$saved=0;if($code!==''){$rate=q('SELECT percent FROM onb_discounts WHERE code=? AND active=1 FOR UPDATE',[$code])->fetchColumn();if(!$rate)throw new RuntimeException('Invalid discount code.');$fixed=q('SELECT amount FROM onb_discount_fixed WHERE code=?',[$code])->fetchColumn();$saved=$fixed!==false?(float)$fixed:round($price*$rate/100,2);$price=round($price-$saved,2);if($price<=0)throw new RuntimeException('Discount exceeds price.');}q('INSERT INTO onb_bookings(ref,trip_id,user_id,agent_id,price) VALUES(?,?,?,?,?)',['ONB-'.strtoupper(bin2hex(random_bytes(6))),$trip,$uid,$agent?:null,$price]);$bid=(int)$db->lastInsertId();if($saved)q('INSERT INTO onb_discount_uses VALUES(?,?,?)',[$bid,$code,$saved]);}
elseif($action==='booking_expense'){if(!p('category')||!p('reference'))throw new RuntimeException('Category and reference required.');q('INSERT INTO onb_booking_expenses(trip_id,category,amount,reference) VALUES(?,?,?,?)',[(int)p('trip_id'),p('category'),bookingAmount('amount'),p('reference')]);}
else{$id=(int)p('id');$b=q('SELECT * FROM onb_bookings WHERE id=? FOR UPDATE',[$id])->fetch();if(!$b)throw new RuntimeException('Booking not found.');$net=bookingNet($id);
if($action==='booking_policy'){$date=p('departure');$visa=p('visa');$reason=p('cancel_reason');$cost=p('nonrecoverable');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date)||!checkdate((int)substr($date,5,2),(int)substr($date,8,2),(int)substr($date,0,4))||!in_array($visa,['pending','approved','refused','not_required'],true)||!in_array($reason,['','voluntary','visa','organizer'],true)||!preg_match('/^\d{1,9}(\.\d{1,2})?$/D',$cost))throw new RuntimeException('Invalid policy details.');q('INSERT INTO onb_booking_policy VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE departure=VALUES(departure),visa=VALUES(visa),flexible=VALUES(flexible),insurance=VALUES(insurance),cancel_reason=VALUES(cancel_reason),nonrecoverable=VALUES(nonrecoverable)',[$id,$date,$visa,p('flexible')==='1'?1:0,p('insurance')==='1'?1:0,$reason?:null,$cost]);}
elseif($action==='booking_stage'){$next=p('stage');$allowed=['quote'=>['accepted','cancelled'],'accepted'=>['confirmed','cancelled'],'confirmed'=>['completed','cancelled'],'completed'=>[],'cancelled'=>[]];if(!in_array($next,$allowed[$b['stage']]??[],true))throw new RuntimeException('Invalid booking transition.');if($next==='confirmed'){$cap=(int)q('SELECT seats FROM trips WHERE id=? FOR UPDATE',[$b['trip_id']])->fetchColumn();$used=(int)q("SELECT COUNT(*) FROM onb_bookings WHERE trip_id=? AND stage IN ('confirmed','completed')",[$b['trip_id']])->fetchColumn();if($used >= $cap)throw new RuntimeException('No seats available.');if($net<min(500,(float)$b['price']))throw new RuntimeException('Record required deposit first.');}if($next==='completed'&&$net<(float)$b['price'])throw new RuntimeException('Outstanding balance.');q('UPDATE onb_bookings SET stage=? WHERE id=?',[$next,$id]);if($next==='confirmed')q('INSERT IGNORE INTO onb_booking_notifications(booking_id) VALUES(?)',[$id]);if($next==='cancelled')q("UPDATE onb_departure_requests r JOIN onb_checkout x ON x.request_id=r.id SET r.status='declined' WHERE x.booking_id=?",[$id]);if($next==='completed'&&$b['agent_id']){$person=q('SELECT name,email FROM users WHERE id=?',[$b['user_id']])->fetch();q("INSERT INTO onb_agent_leads(agent_id,trip_id,name,email,stage,notes) VALUES(?,?,?,?,'won',?)",[$b['agent_id'],$b['trip_id'],$person['name'],$person['email'],'Booking '.$b['ref'].' — review for commission']);q('INSERT INTO onb_booking_agent_link VALUES(?,?)',[$id,(int)$db->lastInsertId()]);}}
elseif($action==='booking_money'){$kind=p('kind');$amount=bookingAmount('amount');if(!p('reference')||!in_array($kind,['payment','refund'],true))throw new RuntimeException('Reference required.');if($kind==='payment'&&(!in_array($b['stage'],['accepted','confirmed'],true)||round($net+(float)$amount,2)>(float)$b['price']))throw new RuntimeException('Payment exceeds balance or booking is not payable.');if($kind==='refund'&&q('SELECT 1 FROM onb_booking_agent_link WHERE booking_id=?',[$id])->fetchColumn())throw new RuntimeException('Linked commission requires accounting adjustment before refund.');if($kind==='refund'&&(float)$amount>$net)throw new RuntimeException('Refund exceeds net payments.');q('INSERT INTO onb_booking_money(booking_id,kind,amount,reference) VALUES(?,?,?,?)',[$id,$kind,$amount,p('reference')]);}
else throw new RuntimeException('Unknown action.');}
$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}go('page=bookings');}
function bookingView($u,$admin){if(!$u){echo '<p>Sign in required.</p>';return;}bookingSetup();bookingCancellationSetup();businessSetup();$rows=q('SELECT b.*,t.title,u.name,u.email FROM onb_bookings b JOIN trips t ON t.id=b.trip_id JOIN users u ON u.id=b.user_id'.($admin?'':' WHERE b.user_id=?').' ORDER BY b.id DESC',$admin?[]:[$u['id']])->fetchAll();?>
<div class="onb-dash"><div class="dash-hero"><span>BOOKING OPERATIONS</span><h1><?=$admin?'Bookings & finance':'My bookings'?></h1><p>Quotes, reservations, payments and balances in one place.</p></div>
<?php if($admin):?><details><summary>Create traveller quotation</summary><?php form('booking_create');field('email','Registered traveller email','','email');?><label>Journey<select name="trip_id"><?php foreach(q('SELECT id,title FROM trips') as $t):?><option value="<?=$t['id']?>"><?=h($t['title'])?></option><?php endforeach;?></select></label><?php field('price','Quoted total CAD');echo '<label>Optional discount code<input name="discount"></label>';?><label>Agent<select name="agent_id"><option value="0">Direct sale</option><?php agentSetup();foreach(q('SELECT a.user_id,u.name FROM onb_agents a JOIN users u ON u.id=a.user_id WHERE a.active=1') as $a):?><option value="<?=$a['user_id']?>"><?=h($a['name'])?></option><?php endforeach;?></select></label><button>Create quote</button></form></details>
<details><summary>Record trip expense</summary><?php form('booking_expense');?><label>Journey<select name="trip_id"><?php foreach(q('SELECT id,title FROM trips') as $t):?><option value="<?=$t['id']?>"><?=h($t['title'])?></option><?php endforeach;?></select></label><?php field('category','Expense category');field('amount','CAD amount');field('reference','Supplier / receipt reference');?><button>Record expense</button></form></details>
<h2>Financial overview</h2><?php foreach(q('SELECT id,title,seats FROM trips') as $t):$rev=0;$cash=0;$due=0;$used=0;foreach($rows as $b){if($b['trip_id']!=$t['id'])continue;$n=bookingNet($b['id']);$cash+=$n;if(in_array($b['stage'],['confirmed','completed'],true)){$rev+=(float)$b['price'];$due+=max(0,(float)$b['price']-$n);$used++;}}$expense=(float)q('SELECT COALESCE(SUM(amount),0) FROM onb_booking_expenses WHERE trip_id=?',[$t['id']])->fetchColumn();?><article><h3><?=h($t['title'])?></h3><p><?=$used?> / <?=$t['seats']?> seats reserved</p><div class="metrics"><?php foreach(['Confirmed booking value'=>$rev,'Net cash collected'=>$cash,'Confirmed balance due'=>$due,'Recorded expenses'=>$expense,'Booking value less recorded expenses'=>$rev-$expense] as $label=>$value):?><article><span><?=h($label)?></span><strong>$<?=number_format($value,2)?></strong></article><?php endforeach;?></div><small>Not accounting profit: excludes unrecorded costs, commissions, rewards and taxes.</small></article><?php endforeach;endif;?>
<h2>Booking register</h2><?php if(!$rows):?><p>No bookings yet.</p><?php endif;foreach($rows as $b):$net=bookingNet($b['id']);?><details><summary><?=h($b['ref'].' · '.$b['title'].' · '.$b['stage'])?></summary><p><?=h($b['name'])?> · Quoted CAD $<?=h($b['price'])?> · Net paid $<?=number_format($net,2)?> · Balance $<?=number_format(max(0,(float)$b['price']-$net),2)?></p><?php bookingPolicyView($b,$admin);businessChecklist($b,$admin);bookingCancellationView($b,$admin);?><div class="dash-table"><table><thead><tr><th>Date</th><th>Type</th><th>CAD</th><th>Reference</th></tr></thead><tbody><?php foreach(q('SELECT * FROM onb_booking_money WHERE booking_id=? ORDER BY id',[$b['id']]) as $m):?><tr><td><?=h($m['created_at'])?></td><td><?=h($m['kind'])?></td><td><?=h($m['amount'])?></td><td><?=h($m['reference'])?></td></tr><?php endforeach;?></tbody></table></div><p><a href="?page=booking_document&amp;id=<?=$b['id']?>">Printable booking statement</a></p><?php if($admin):form('booking_stage');?><input type="hidden" name="id" value="<?=$b['id']?>"><label>Next status<select name="stage"><?php foreach(['accepted','confirmed','completed','cancelled'] as $stage):?><option><?=h($stage)?></option><?php endforeach;?></select></label><button>Update status</button></form><?php form('booking_money');?><input type="hidden" name="id" value="<?=$b['id']?>"><label>Transaction<select name="kind"><option>payment</option><option>refund</option></select></label><?php field('amount','CAD amount');field('reference','Transaction reference');?><button>Record transaction</button></form><?php endif;?></details><?php endforeach;?></div><?php }
function bookingDocument($u,$admin){if(!$u){http_response_code(403);exit;}bookingSetup();$b=q('SELECT b.*,t.title,u.name FROM onb_bookings b JOIN trips t ON t.id=b.trip_id JOIN users u ON u.id=b.user_id WHERE b.id=?',[(int)($_GET['id']??0)])->fetch();if(!$b||(!$admin&&(int)$b['user_id']!==(int)$u['id'])){http_response_code(404);exit;}header('Cache-Control: no-store');?><!doctype html><html><head><meta charset="utf-8"><title>Booking statement</title><link rel="stylesheet" href="style.css"></head><body><main><h1>Our Next Boarding</h1><h2>Booking statement <?=h($b['ref'])?></h2><p><?=h($b['name'].' · '.$b['title'].' · '.$b['stage'])?></p><p>Quoted CAD $<?=h($b['price'])?> · Net paid CAD $<?=number_format(bookingNet($b['id']),2)?></p><p>Print or save as PDF using your browser. This is a booking statement, not a tax invoice.</p></main></body></html><?php exit;}
